const clone = (value) => {
  if (value === undefined) return undefined;
  return structuredClone(value);
};

/**
 * Normalize the small envelope shared by all KKB-V2 workflows.
 * Business configuration is deliberately not inferred here; it is read only
 * by the Config Gateway from the live Google Sheets tables.
 */
function normalizeEnvelope(input) {
  if (!input || typeof input !== 'object') {
    throw new TypeError('workflow envelope must be an object');
  }

  const requestId = input.request_id;
  const operationId = input.operation_id;
  if (!requestId || !operationId) {
    throw new Error('workflow envelope requires request_id and operation_id');
  }

  return {
    request_id: String(requestId),
    operation_id: String(operationId),
    event_type: input.event_type ? String(input.event_type) : 'UNKNOWN',
    actor_user_id: input.actor_user_id == null ? null : String(input.actor_user_id),
    branch_id: input.branch_id == null || input.branch_id === '' ? null : String(input.branch_id),
    business_date: input.business_date == null || input.business_date === '' ? null : String(input.business_date),
    config_version: input.config_version == null || input.config_version === '' ? null : String(input.config_version),
    payload: input.payload && typeof input.payload === 'object' ? clone(input.payload) : {},
  };
}

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

const rotr = (value, bits) => (value >>> bits) | (value << (32 - bits));

/** Dependency-free SHA-256 for Node tests and n8n Code nodes. */
function sha256(input) {
  const bytes = new TextEncoder().encode(String(input));
  const bitLength = bytes.length * 8;
  const paddedLength = Math.ceil((bytes.length + 9) / 64) * 64;
  const padded = new Uint8Array(paddedLength);
  padded.set(bytes);
  padded[bytes.length] = 0x80;
  const view = new DataView(padded.buffer);
  view.setUint32(paddedLength - 8, Math.floor(bitLength / 0x100000000));
  view.setUint32(paddedLength - 4, bitLength >>> 0);

  let h0 = 0x6a09e667;
  let h1 = 0xbb67ae85;
  let h2 = 0x3c6ef372;
  let h3 = 0xa54ff53a;
  let h4 = 0x510e527f;
  let h5 = 0x9b05688c;
  let h6 = 0x1f83d9ab;
  let h7 = 0x5be0cd19;

  const schedule = new Uint32Array(64);
  for (let offset = 0; offset < paddedLength; offset += 64) {
    for (let i = 0; i < 16; i += 1) schedule[i] = view.getUint32(offset + i * 4);
    for (let i = 16; i < 64; i += 1) {
      const s0 = rotr(schedule[i - 15], 7) ^ rotr(schedule[i - 15], 18) ^ (schedule[i - 15] >>> 3);
      const s1 = rotr(schedule[i - 2], 17) ^ rotr(schedule[i - 2], 19) ^ (schedule[i - 2] >>> 10);
      schedule[i] = (schedule[i - 16] + s0 + schedule[i - 7] + s1) >>> 0;
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;
    let f = h5;
    let g = h6;
    let h = h7;
    for (let i = 0; i < 64; i += 1) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const choice = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + choice + K[i] + schedule[i]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const majority = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + majority) >>> 0;
      h = g;
      g = f;
      f = e;
      e = (d + temp1) >>> 0;
      d = c;
      c = b;
      b = a;
      a = (temp1 + temp2) >>> 0;
    }
    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
    h5 = (h5 + f) >>> 0;
    h6 = (h6 + g) >>> 0;
    h7 = (h7 + h) >>> 0;
  }

  return [h0, h1, h2, h3, h4, h5, h6, h7]
    .map((value) => value.toString(16).padStart(8, '0'))
    .join('');
}


const asText = (value) => (value == null ? '' : String(value).trim());

const safeId = (value) => asText(value).replace(/[^A-Za-z0-9._-]/g, '_');

const itemCode = (item) => asText(item?.ma_bia ?? item?.item_code ?? item?.item_id);
const itemName = (item) => asText(item?.ten_bia ?? item?.item_name ?? item?.name);
const itemUnit = (item) => asText(item?.don_vi_dem ?? item?.unit ?? item?.count_unit);

function displayLabel(item) {
  return `${itemCode(item)} — ${itemName(item)} — ${itemUnit(item)}`;
}

function canonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${canonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function stagedPlan({ operationId, requestId, operationType, rows, now }) {
  const checksum = sha256(canonicalJson(rows));
  const operationRow = {
    operation_id: operationId,
    request_id: requestId,
    operation_type: operationType,
    idempotency_key: requestId || operationId,
    expected_row_count: String(rows.length),
    actual_row_count: '',
    checksum,
    status: 'PREPARED',
    error_id: '',
    created_at: now,
    updated_at: now,
  };
  const plan = [{ sheet: 'OPERATION', action: 'APPEND', row: operationRow }];
  for (const { sheet, row } of rows) plan.push({ sheet, action: 'APPEND', row });
  for (const { sheet, row, match_column: matchColumn } of rows) {
    plan.push({
      sheet,
      action: 'UPDATE',
      match: { [matchColumn]: row[matchColumn] },
      patch: { status: 'COMMITTED', write_state: 'COMMITTED', updated_at: now },
    });
  }
  plan.push({
    sheet: 'OPERATION',
    action: 'UPDATE',
    match: { operation_id: operationId },
    patch: { status: 'COMMITTED', actual_row_count: String(rows.length), updated_at: now },
  });
  return plan;
}

function decimalPlaces(value) {
  const text = asText(value).toLowerCase();
  if (text.includes('e')) {
    const [coefficient, exponentText] = text.split('e');
    const exponent = Number(exponentText);
    return Math.max(0, (coefficient.split('.')[1]?.length ?? 0) - exponent);
  }
  return text.split('.')[1]?.length ?? 0;
}

function validateCountValue(value, rules = {}) {
  if (value == null || (typeof value === 'string' && asText(value) === '')) {
    return { status: 'INCOMPLETE', value: null };
  }
  const numericValue = typeof value === 'number' ? value : Number(asText(value));
  if (!Number.isFinite(numericValue)) {
    return { status: 'INVALID', value: null, error_code: 'COUNT_NOT_NUMERIC' };
  }
  if (numericValue < 0) {
    return { status: 'INVALID', value: numericValue, error_code: 'COUNT_NEGATIVE' };
  }
  const configuredPrecision = rules.decimal_places ?? rules.so_le ?? rules.decimals;
  if (asText(configuredPrecision) !== '' && decimalPlaces(value) > Number(configuredPrecision)) {
    return { status: 'INVALID', value: numericValue, error_code: 'COUNT_DECIMAL_NOT_ALLOWED' };
  }
  const configuredStep = Number(rules.step ?? rules.buoc_dem);
  if (Number.isFinite(configuredStep) && configuredStep > 0) {
    const quotient = numericValue / configuredStep;
    if (Math.abs(quotient - Math.round(quotient)) > 1e-9) {
      return { status: 'INVALID', value: numericValue, error_code: 'COUNT_STEP_INVALID' };
    }
  }
  const minimum = Number(rules.min ?? rules.ton_min);
  if (Number.isFinite(minimum) && numericValue < minimum) return { status: 'INVALID', value: numericValue, error_code: 'COUNT_BELOW_MIN' };
  const maximum = Number(rules.max ?? rules.ton_max);
  if (Number.isFinite(maximum) && numericValue > maximum) return { status: 'INVALID', value: numericValue, error_code: 'COUNT_ABOVE_MAX' };
  return { status: 'VALID', value: numericValue };
}

function planCountSave({
  session = {},
  item = {},
  current_entry: currentEntry,
  value,
  expected_revision: expectedRevision = 0,
  correction_reason: correctionReason,
  operation_id: operationId,
  request_id: requestId,
  actor_user_id: actorUserId,
  now,
} = {}) {
  const validation = validateCountValue(value, item);
  if (validation.status !== 'VALID') return { ok: false, ...validation, write_plan: [] };
  const currentSessionStatus = asText(session.status).toUpperCase();
  if (currentSessionStatus === 'EXPIRED') return { ok: false, error_code: 'SESSION_EXPIRED_REOPEN_REQUIRED', write_plan: [] };
  if (currentSessionStatus === 'CANCELLED') return { ok: false, error_code: 'SESSION_CANCELLED', write_plan: [] };

  const currentRevision = Number(currentEntry?.revision ?? 0);
  const expected = Number(expectedRevision ?? 0);
  if (expected !== currentRevision) {
    return {
      ok: false,
      error_code: 'COUNT_REVISION_CONFLICT',
      conflict: {
        expected_revision: expected,
        current_revision: currentRevision,
        current_value: currentEntry?.ton_thuc_te ?? null,
        submitted_value: value,
        current_entry_id: currentEntry?.entry_id ?? null,
      },
      write_plan: [],
    };
  }

  const sessionStatus = asText(session.status).toUpperCase();
  if (['FINALIZED', 'LOCKED', 'CLOSED'].includes(sessionStatus)) {
    const reason = asText(correctionReason);
    if (!reason) {
      return {
        ok: false,
        error_code: 'CORRECTION_REASON_REQUIRED',
        write_plan: [],
      };
    }
    const code = itemCode(item);
    const adjustment = {
      adjustment_id: `adjust-${safeId(session.session_id)}-${safeId(code)}-r${currentRevision + 1}`,
      session_id: asText(session.session_id),
      branch_id: asText(session.branch_id),
      business_date: asText(session.business_date),
      ma_bia: code,
      target_entry_id: asText(currentEntry?.entry_id),
      from_value: currentEntry?.ton_thuc_te ?? null,
      to_value: validation.value,
      reason,
      actor_user_id: asText(actorUserId),
      status: 'PREPARED',
      operation_id: asText(operationId),
      write_state: 'PREPARED',
      created_at: asText(now),
      approved_at: '',
      approved_by: '',
    };
    return {
      ok: true,
      action: 'ADJUSTMENT_PLANNED',
      adjustment: { ...adjustment, status: 'COMMITTED', write_state: 'COMMITTED' },
      write_plan: stagedPlan({
        operationId: asText(operationId),
        requestId: asText(requestId),
        operationType: 'COUNT_CORRECTION',
        rows: [{ sheet: 'DIEU_CHINH_SO', row: adjustment, match_column: 'adjustment_id' }],
        now: asText(now),
      }),
    };
  }

  const nextRevision = currentRevision + 1;
  const code = itemCode(item);
  const entry = {
    entry_id: `count-${safeId(session.session_id)}-${safeId(code)}-r${nextRevision}`,
    session_id: asText(session.session_id),
    branch_id: asText(session.branch_id),
    business_date: asText(session.business_date),
    config_snapshot_id: asText(session.config_snapshot_id),
    ma_bia: code,
    ten_bia: itemName(item),
    don_vi_dem: itemUnit(item),
    display_label: displayLabel(item),
    ton_thuc_te: validation.value,
    revision: nextRevision,
    supersedes_entry_id: asText(currentEntry?.entry_id),
    status: 'PREPARED',
    explanation: '',
    actor_user_id: asText(actorUserId),
    idempotency_key: `${asText(requestId) || asText(operationId)}:${asText(session.session_id)}:${code}:${nextRevision}`,
    operation_id: asText(operationId),
    write_state: 'PREPARED',
    created_at: asText(now),
    updated_at: asText(now),
  };
  return {
    ok: true,
    action: 'COUNT_SAVED',
    entry: { ...entry, status: 'COMMITTED', write_state: 'COMMITTED' },
    write_plan: stagedPlan({
      operationId: asText(operationId),
      requestId: asText(requestId),
      operationType: 'SAVE_COUNT',
      rows: [{ sheet: 'BIA_LOG', row: entry, match_column: 'entry_id' }],
      now: asText(now),
    }),
  };
}


const reviewText = (value) => (value == null ? '' : String(value).trim());

function numberOrNull(value) {
  if (value == null || reviewText(value) === '') return null;
  const number = Number(value);
  return Number.isFinite(number) ? number : null;
}

function labelFor(item) {
  return item.display_label || `${reviewText(item.ma_bia)} — ${reviewText(item.ten_bia)} — ${reviewText(item.don_vi_dem)}`;
}

function varianceStatus(variance, item) {
  const magnitude = Math.abs(variance);
  const redThreshold = numberOrNull(item.nguong_chenh_do);
  const yellowThreshold = numberOrNull(item.nguong_chenh_vang);
  if (redThreshold !== null && magnitude > redThreshold) return 'RED';
  if (yellowThreshold !== null && magnitude > yellowThreshold) return 'YELLOW';
  return 'NORMAL';
}

function reviewCanonicalJson(value) {
  if (Array.isArray(value)) return `[${value.map(reviewCanonicalJson).join(',')}]`;
  if (value && typeof value === 'object') {
    return `{${Object.keys(value).sort().map((key) => `${JSON.stringify(key)}:${reviewCanonicalJson(value[key])}`).join(',')}}`;
  }
  return JSON.stringify(value);
}

function finalizeWritePlan({ session, finalized, auditRows, operationId, requestId, now }) {
  const checksumInput = { finalized, audit_rows: auditRows };
  const operationRow = {
    operation_id: operationId,
    request_id: requestId,
    operation_type: 'FINALIZE_INVENTORY_SESSION',
    idempotency_key: requestId || operationId,
    expected_row_count: String(auditRows.length + 1),
    actual_row_count: '',
    checksum: sha256(reviewCanonicalJson(checksumInput)),
    status: 'PREPARED',
    error_id: '',
    created_at: now,
    updated_at: now,
  };
  const plan = [
    { sheet: 'OPERATION', action: 'APPEND', row: operationRow },
    {
      sheet: 'PHIEN_KIEM_KE',
      action: 'UPDATE',
      match: { session_id: session.session_id },
      patch: {
        status: 'FINALIZE_PREPARED',
        write_state: 'PREPARED',
        operation_id: operationId,
        updated_at: now,
      },
    },
  ];
  for (const row of auditRows) plan.push({ sheet: 'EVENT_LOG', action: 'APPEND', row });
  for (const row of auditRows) {
    plan.push({
      sheet: 'EVENT_LOG',
      action: 'UPDATE',
      match: { event_id: row.event_id },
      patch: { status: 'COMMITTED', write_state: 'COMMITTED', updated_at: now },
    });
  }
  plan.push({
    sheet: 'PHIEN_KIEM_KE',
    action: 'UPDATE',
    match: { session_id: session.session_id },
    patch: {
      ...finalized,
      write_state: 'COMMITTED',
      operation_id: operationId,
    },
  });
  plan.push({
    sheet: 'OPERATION',
    action: 'UPDATE',
    match: { operation_id: operationId },
    patch: { status: 'COMMITTED', actual_row_count: String(auditRows.length + 1), updated_at: now },
  });
  return plan;
}

function reviewInventorySession({
  session = {},
  count_entries: countEntries = [],
  theoretical_by_item: theoreticalByItem = {},
  now,
} = {}) {
  const entries = new Map((Array.isArray(countEntries) ? countEntries : [])
    .filter((entry) => reviewText(entry?.ma_bia))
    .map((entry) => [reviewText(entry.ma_bia), entry]));
  const summary = [];
  const missingItemCodes = [];
  const invalidItemCodes = [];
  const redItems = [];

  for (const item of Array.isArray(session.catalog) ? session.catalog : []) {
    const code = reviewText(item.ma_bia);
    const entry = entries.get(code);
    const validation = validateCountValue(entry?.ton_thuc_te);
    if (!entry || validation.status === 'INCOMPLETE') missingItemCodes.push(code);
    if (entry && validation.status === 'INVALID') invalidItemCodes.push(code);

    const theoretical = numberOrNull(theoreticalByItem?.[code]);
    const actual = validation.status === 'VALID' ? validation.value : null;
    const variance = actual === null || theoretical === null ? null : actual - theoretical;
    const status = variance === null ? 'INCOMPLETE' : varianceStatus(variance, item);
    const line = {
      ma_bia: code,
      ten_bia: reviewText(item.ten_bia),
      don_vi_dem: reviewText(item.don_vi_dem),
      display_label: labelFor(item),
      ton_thuc_te: actual,
      revision: entry?.revision ?? 0,
      ton_ly_thuyet: theoretical,
      variance,
      variance_status: status,
      requires_explanation: status === 'RED',
      explanation: reviewText(entry?.explanation),
    };
    summary.push(line);
    if (status === 'RED') redItems.push(line);
  }

  return {
    ok: true,
    status: missingItemCodes.length || invalidItemCodes.length ? 'REVIEW_INCOMPLETE' : 'REVIEW_READY',
    session_id: reviewText(session.session_id),
    reviewed_at: reviewText(now),
    summary,
    missing_item_codes: missingItemCodes,
    invalid_item_codes: invalidItemCodes,
    red_items: redItems,
  };
}

function finalizeInventorySession({
  session = {},
  review = {},
  confirmed,
  explanations = {},
  operation_id: operationId,
  request_id: requestId,
  actor_user_id: actorUserId,
  now,
} = {}) {
  if (confirmed !== true) {
    return {
      ok: false,
      error_code: 'FINALIZE_CONFIRMATION_REQUIRED',
      write_plan: [],
    };
  }
  const missingExplanationItemCodes = (Array.isArray(review.red_items) ? review.red_items : [])
    .map((item) => reviewText(item.ma_bia))
    .filter((code) => !reviewText(explanations?.[code]));
  if (missingExplanationItemCodes.length > 0) {
    return {
      ok: false,
      error_code: 'RED_VARIANCE_EXPLANATION_REQUIRED',
      missing_explanation_item_codes: missingExplanationItemCodes,
      write_plan: [],
    };
  }
  if (review.status !== 'REVIEW_READY' || review.missing_item_codes?.length || review.invalid_item_codes?.length) {
    return {
      ok: false,
      error_code: 'FINALIZE_REVIEW_INCOMPLETE',
      write_plan: [],
    };
  }

  const finalOperationId = reviewText(operationId);
  const finalRequestId = reviewText(requestId);
  const finalActorUserId = reviewText(actorUserId);
  const finalNow = reviewText(now);
  const auditRows = (Array.isArray(review.red_items) ? review.red_items : []).map((item) => ({
    event_id: `event-${reviewText(session.session_id)}-red-${reviewText(item.ma_bia)}-${finalOperationId}`,
    event_key: `${finalOperationId}:RED_VARIANCE_EXPLAINED:${reviewText(item.ma_bia)}`,
    event_type: 'RED_VARIANCE_EXPLAINED',
    entity_type: 'COUNT_ITEM',
    entity_id: reviewText(item.ma_bia),
    branch_id: reviewText(session.branch_id),
    actor_user_id: finalActorUserId,
    reason: reviewText(explanations?.[item.ma_bia]),
    payload_json: JSON.stringify({ variance: item.variance, session_id: session.session_id }),
    status: 'PREPARED',
    operation_id: finalOperationId,
    write_state: 'PREPARED',
    created_at: finalNow,
  }));
  const finalized = {
    session_id: reviewText(session.session_id),
    status: 'FINALIZED',
    finalized_by: finalActorUserId,
    finalized_at: finalNow,
    red_item_count: auditRows.length,
    warning_status: auditRows.length > 0 ? 'RED_EXPLAINED' : 'OK',
    updated_at: finalNow,
  };
  return {
    ok: true,
    action: 'FINALIZED',
    finalized,
    write_plan: finalizeWritePlan({
      session,
      finalized,
      auditRows,
      operationId: finalOperationId,
      requestId: finalRequestId,
      now: finalNow,
    }),
  };
}


const triggerInput = $('Execute Workflow Trigger').first()?.json ?? {};
const envelope = normalizeEnvelope(triggerInput.envelope ?? triggerInput);
const payload = envelope.payload ?? {};
const intent = String(payload.intent ?? payload.action ?? 'SAVE_COUNT').toUpperCase();
let result;
if (intent === 'REVIEW') {
  result = reviewInventorySession(payload);
} else if (intent === 'FINALIZE') {
  result = finalizeInventorySession(payload);
} else {
  result = planCountSave({ ...payload, operation_id: envelope.operation_id, request_id: envelope.request_id, actor_user_id: envelope.actor_user_id });
}
return [{ json: { ...result, request_id: envelope.request_id, operation_id: envelope.operation_id } }];
